export type Session={minutes:number;completed:boolean};
export type Summary={minutes:number;sessions:number};
export function summarize(input:readonly Session[]):Summary {
 const result:Summary={minutes:0,sessions:0};
 for(const session of input){
  if(session.completed && Number.isFinite(session.minutes) && session.minutes>=0){result.minutes+=session.minutes;result.sessions++;}
 }
 return result;
}

