export type Course={id:string;title:string;minutes:number};
export type ParseResult={ok:true;value:Course}|{ok:false;error:string};
export function parseCourse(input:unknown):ParseResult {
 if(typeof input!=="object"||input===null||!("id" in input)||!("title" in input)||!("minutes" in input)) return {ok:false,error:"Missing course fields"};
 if(typeof input.id!=="string"||!input.id.trim()||typeof input.title!=="string"||!input.title.trim()||typeof input.minutes!=="number"||!Number.isFinite(input.minutes)||input.minutes<0) return {ok:false,error:"Invalid course fields"};
 return {ok:true,value:{id:input.id.trim(),title:input.title.trim(),minutes:input.minutes}};
}

