export type Course={id:string;title:string};
export type Page={items:Course[];nextOffset:number|null};
export function search(courses:readonly Course[],query:string,offset:number,limit:number):Page {
 if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<=0) throw new Error("Invalid pagination");
 const q=query.trim().toLowerCase();
 const matches=courses.filter(c=>c.title.toLowerCase().includes(q));
 const items=matches.slice(offset,offset+limit);
 return {items,nextOffset:offset+items.length<matches.length?offset+items.length:null};
}

